'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',mic:'M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'M20 6 9 17l-5-5',chevron:'m9 5 7 7-7 7',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',history:'M3 12a9 9 0 1 0 2.5-6.3 M3 3v6h6 M12 7v5l3 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',logout:'M9 21H5V3h4 M14 8l5 4-5 4 M9 12h10',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z M20 2v4 M18 4h4',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',close:'m6 6 12 12 M6 18 18 6',print:'M6 9V3h12v6 M6 17H3V9h18v8h-3 M6 14h12v7H6z',arrow:'M19 12H5 M12 5l-7 7 7 7',pause:'M8 4v16 M16 4v16',stop:'M5 5h14v14H5z',menu:'M3 6h18 M3 12h18 M3 18h18',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',book:'M4 3h6l2 2 2-2h6v17h-6l-2 2-2-2H4z M12 5v17',pill:'m9 15 6-6 M5 19a6 6 0 0 1 0-8l6-6a6 6 0 0 1 8 8l-6 6a6 6 0 0 1-8 0'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const initials=n=>n.replace(/^Dr\s+/,'').split(' ').slice(0,2).map(x=>x[0]).join('');
const date=v=>new Date(v).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
const state={data:null,page:'queue',active:null,tab:'all',search:'',draft:null,transcript:'',dirty:false,busy:false,recorder:null,stream:null,recording:false,paused:false,seconds:0,timer:null,history:[],proposal:null};
let toastTimer;
function toast(message,failure=false){const el=$('#toast');el.textContent=message;el.className='visible'+(failure?' failure':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',failure?10000:4500);}
async function api(path,body){const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':state.data?.csrf||''},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok){if(response.status===401&&path!=='login'){state.data=null;renderLogin();}throw new Error(data.error||'Request failed.');}return data;}
async function run(task){if(state.busy)return;state.busy=true;document.body.setAttribute('aria-busy','true');$$('button').forEach(b=>{if(!b.disabled){b.dataset.busyDisabled='yes';b.disabled=true;}});try{return await task();}catch(e){toast(e.message,true);}finally{state.busy=false;document.body.removeAttribute('aria-busy');$$('[data-busy-disabled]').forEach(b=>{b.disabled=false;delete b.dataset.busyDisabled;});}}
async function refresh(){state.data=await api('bootstrap');}
function logo(){return `<div class="logo"><div class="logo-mark">l.</div><div>Lumrivo<span>CLINICAL WORKSPACE</span></div></div>`;}
function badge(status){const map={waiting:['Waiting','amber'],draft:['In review','purple'],approved:['Approved','green'],in_consultation:['In consultation','purple']};const v=map[status]||[status,''];return `<span class="badge ${v[1]}"><span class="dot"></span>${esc(v[0])}</span>`;}
function renderLogin(){stopTracks();$('#app').innerHTML=`<main class="login-page"><section class="login-art">${logo()}<div class="login-copy"><div class="eyebrow" style="color:#8de0d0">MORE ATTENTION. BETTER CONTINUITY.</div><h1>A conversation today.<br>A clearer journey<br>for every patient.</h1><p>From the first consultation to the next visit. Capture the details, review the plan, and send patients home with clarity.</p><div class="mini-record"><div class="flex"><span class="flex">${icon('shield')} Clinician-reviewed care</span><span class="badge green">Connected history</span></div><div class="mini-line"></div><div class="mini-line" style="width:65%"></div><div class="mini-line" style="width:76%"></div><div class="flex" style="margin-top:22px;color:#8de0d0">${icon('check')} Clear instructions. Accessible records.</div></div></div><div class="micro muted">A Lumrivo product · Built around the consultation</div></section><section class="login-form"><div class="login-inner"><span class="badge purple">HOSPITAL DEMONSTRATION</span><h2 style="margin-top:21px">Welcome to your workspace</h2><p>Sign in to continue to your hospital.</p><form id="login-form"><div class="row"><label for="email">Work email</label><input id="email" type="email" autocomplete="username" required value="meera@demo.lumrivo.com"></div><div class="row"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" required placeholder="Enter your workspace password"></div><div id="login-error" role="alert"></div><button class="primary" type="submit">Sign in to workspace ${icon('chevron')}</button></form><div class="eyebrow">Choose a demonstration role</div><div class="demo-accounts"><button data-email="meera">General physician</button><button data-email="arjun">Orthopaedics</button><button data-email="sana">Dermatology</button><button data-email="reception">Reception</button><button data-email="admin">Administrator</button></div><p class="login-footer">Fictional patients only. This release is for product demonstrations and has not been validated for real-patient care. No automatic prescribing or treatment recommendations.</p></div></section></main>`;
$$('[data-email]').forEach(b=>b.onclick=()=>{$('#email').value=b.dataset.email+'@demo.lumrivo.com';$('#password').focus();});
$('#login-form').onsubmit=async ev=>{ev.preventDefault();await run(async()=>{try{await api('login',{email:$('#email').value,password:$('#password').value});await refresh();state.page='queue';state.active=null;render();}catch(e){$('#login-error').className='error row';$('#login-error').textContent=e.message;}});};}
function shell(body){const d=state.data,u=d.user;const nav=[['queue','grid','Overview & queue'],['patients','users','Patient directory']];if(u.role==='doctor')nav.push(['history','history','Consultation history']);if(u.role==='admin')nav.push(['settings','settings','Hospital settings']);return `<div class="shell"><aside class="sidebar">${logo()}<div class="nav-label eyebrow">YOUR WORKSPACE</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,ic,title])=>`<button data-nav="${id}" class="${state.page===id?'active':''}">${icon(ic)} ${title}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><strong>${icon('heart')} A clearer patient journey</strong>Capture the consultation.<br>Review every detail.<br>Keep the history connected.</div><div class="user-chip"><div class="avatar">${esc(initials(u.name))}</div><div><div class="name">${esc(u.name)}</div><div class="muted">${esc(u.specialty||u.role)}</div></div><button class="quiet icon-button" id="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="main"><header class="topbar"><div class="flex"><button class="quiet icon-button mobile-menu" id="mobile-menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumbs">Workspace ${icon('chevron')} <strong>${state.active?'Consultation':({queue:'Overview',patients:'Patients',history:'History',settings:'Settings'}[state.page])}</strong></div></div><div class="topbar-right"><span class="muted">${esc(new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'long'}))}</span><span class="badge ${d.ai_configured?'green':'purple'}">${icon(d.ai_configured?'spark':'shield')}${d.ai_configured?'AI key configured':'Manual + demo mode'}</span><button id="account" class="avatar quiet" aria-label="Account settings">${esc(initials(u.name))}</button></div></header><div class="demo-strip"><span><strong>Demonstration workspace</strong> · Fictional patients and medicines only. Not for clinical use.</span><span>${esc(d.organisation.name)}</span></div><main class="content">${body}</main></div></div>`;}
function render(){if(!state.data)return renderLogin();const html=state.active?consultation():({queue:queue,patients:patients,history:historyPage,settings:settings}[state.page]||queue)();$('#app').innerHTML=shell(html);bindShell();if(state.active)bindConsultation();else if(state.page==='queue')bindQueue();else if(state.page==='patients')bindPatients();else if(state.page==='history')bindHistoryPage();else if(state.page==='settings')bindSettings();}
function allowNavigate(){if(state.recording||state.busy){toast('Stop the recording or wait for processing before leaving this patient.',true);return false;}if(state.dirty&&!confirm('You have unsaved edits. Leave without saving them?'))return false;return true;}
function bindShell(){$$('[data-nav]').forEach(b=>b.onclick=()=>{if(!allowNavigate())return;state.page=b.dataset.nav;state.active=null;state.dirty=false;state.search='';render();});$('#logout').onclick=()=>{if(!allowNavigate())return;run(async()=>{await api('logout',{});state.data=null;state.active=null;renderLogin();});};$('#account').onclick=passwordModal;const m=$('#mobile-menu');if(m)m.onclick=()=>$('.sidebar').classList.toggle('open');}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function queue(){const d=state.data,rows=d.encounters.filter(e=>e.status!=='approved'),waiting=rows.filter(e=>e.status==='waiting').length;return heading(d.user.role==='doctor'?`Good ${new Date().getHours()<12?'morning':'day'}, ${esc(d.user.name.replace(/^Dr\s+/, 'Dr '))}`:'Your hospital, at a glance','A clearer view of today’s consultations and every patient’s next step.',d.user.role!=='doctor'?`<button class="primary" id="new-visit">${icon('plus')} Register a visit</button>`:`<button id="refresh">${icon('history')} Refresh queue</button>`)+`<div class="metrics">${[['Patient visits',d.encounters.length,'In this workspace','users'],['Waiting',waiting,'Ready for consultation','clock'],['Drafts to review',rows.length-waiting,'Awaiting clinician approval','file'],['Approved records',d.encounters.filter(e=>e.status==='approved').length,'Saved for continuity','check']].map(([title,n,sub,ic])=>`<div class="metric"><div class="metric-top">${title}${icon(ic)}</div><div class="metric-num">${n}</div><div class="micro muted" style="margin-top:5px">${sub}</div></div>`).join('')}</div><div class="queue-layout"><section class="card"><div class="card-head"><div><h2>Consultation queue</h2><p class="muted micro" style="margin-top:5px">Each token stays connected to a patient and doctor.</p></div><span class="badge">${d.doctors.length} doctors configured</span></div><div class="toolbar"><div class="tabs">${[['all','All visits'],['waiting','Waiting'],['draft','In review'],['approved','Approved']].map(([v,l])=>`<button data-tab="${v}" class="${state.tab===v?'active':''}">${l}</button>`).join('')}</div><div class="search">${icon('search')}<input id="queue-search" aria-label="Search patient or hospital ID" placeholder="Search patient or hospital ID" value="${esc(state.search)}"></div></div><div id="queue-table">${queueTable()}</div><div class="card-foot micro muted">${icon('shield')} Doctor review is required before any prescription is issued.</div></section><aside class="queue-aside stack"><section class="card card-pad"><div class="feature-icon">${icon('heart')}</div><h2>Every visit, connected.</h2><p class="muted" style="font-size:12px;margin-top:10px">Make the consultation count beyond the doctor’s room.</p>${[['Capture the details','Conversation or manual notes, connected to the right patient.'],['Review the care plan','Medicines, tests and advice checked by the doctor.'],['Give patients clarity','Readable instructions and a history for the next visit.']].map(([t,p],i)=>`<div class="journey-item"><div class="step">0${i+1}</div><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</section><section class="card card-pad"><h3>Workspace readiness</h3><div class="provider">${icon('spark')}<div><span>${d.ai_configured?'AI provider configured':'AI provider not connected'}</span><p class="micro muted">${d.ai_configured?'Capture and extraction available for testing.':'Manual workflow and fictional walkthrough available.'}</p></div></div><div class="info">${d.ai_configured?'Review all generated content. Provider accuracy has not been clinically validated.':'Add a server-side API key to test actual transcription and draft generation.'}</div></section></aside></div>`;}
function queueTable(){const d=state.data;const rows=d.encounters.filter(e=>(state.tab==='all'||e.status===state.tab)&&(e.name+' '+e.mrn+' '+e.doctor_name).toLowerCase().includes(state.search.toLowerCase()));if(!rows.length)return `<div class="empty">${icon('users')}<p>No matching visits.</p></div>`;return `<div class="table-wrap"><table><thead><tr><th>Patient</th><th>Token</th><th>Doctor / specialty</th><th>Status</th><th></th></tr></thead><tbody>${rows.map((e,i)=>`<tr><td><div class="patient-cell"><div class="avatar ${i%2?'mint':''}">${esc(initials(e.name))}</div><div><strong>${esc(e.name)}</strong><small>${esc(e.mrn)} · ${e.age}y · ${esc(e.sex)}</small></div></div></td><td><span class="token">#${e.token}</span></td><td>${esc(e.doctor_name)}<div class="muted micro" style="margin-top:5px">${esc(e.specialty)} · ${date(e.created)}</div></td><td>${badge(e.status)}</td><td>${d.user.role==='doctor'?`<button class="small ${e.status==='approved'?'':'primary'}" data-open="${e.id}">${e.status==='approved'?'View record':'Open visit'}${icon('chevron')}</button>`:'<span class="micro muted">Assigned</span>'}</td></tr>`).join('')}</tbody></table></div>`;}
function bindQueue(){const refreshButton=$('#refresh');if(refreshButton)refreshButton.onclick=()=>run(async()=>{await refresh();render();});const n=$('#new-visit');if(n)n.onclick=visitModal;$$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render();});$('#queue-search').oninput=ev=>{state.search=ev.target.value;$('#queue-table').innerHTML=queueTable();bindOpen();};bindOpen();}
function bindOpen(){$$('[data-open]').forEach(b=>b.onclick=()=>openEncounter(b.dataset.open));}
async function openEncounter(id){if(!allowNavigate())return;await run(async()=>{await refresh();const e=state.data.encounters.find(x=>x.id===id);if(!e)throw new Error('Visit is no longer accessible.');state.active=id;state.draft=clone(e.draft);state.transcript=e.transcript||'';state.dirty=false;state.history=(await api(`encounters/${id}/history`)).documents;state.seconds=0;render();});}
function active(){return state.data.encounters.find(e=>e.id===state.active);}
function patients(){return heading('Patient directory','A persistent identity across consultations. Shared phone numbers do not merge patient records.',state.data.user.role!=='doctor'?`<button class="primary" id="new-patient">${icon('plus')} Add fictional patient</button>`:'')+`<section class="card"><div class="card-head"><h2>Hospital patients</h2><span class="badge">${state.data.patients.length} records</span></div><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Hospital ID</th><th>Age / sex</th><th>Contact</th><th>Visits</th></tr></thead><tbody>${state.data.patients.map(p=>`<tr><td><div class="patient-cell"><div class="avatar">${esc(initials(p.name))}</div><strong>${esc(p.name)}</strong></div></td><td>${esc(p.mrn)}</td><td>${p.age}y · ${esc(p.sex)}</td><td>${esc(p.phone)||'Not provided'}</td><td>${state.data.encounters.filter(e=>e.patient===p.id).length}</td></tr>`).join('')}</tbody></table></div></section><div class="info" style="margin-top:20px">Fictional demonstration records. Patient identity must be checked at each visit; a token or phone number alone is not an identity check.</div>`;}
function bindPatients(){const b=$('#new-patient');if(b)b.onclick=patientModal;}
function historyPage(){const rows=state.data.encounters.filter(e=>e.status==='approved');return heading('Consultation history','Approved records stay connected to the patient, with their author and version.')+`<div class="stack">${rows.length?rows.map(e=>`<section class="card card-pad flex between wrap"><div class="patient-cell"><div class="avatar mint">${esc(initials(e.name))}</div><div><strong>${esc(e.name)}</strong><small>${esc(e.mrn)} · ${date(e.updated)} · ${esc(e.specialty)}</small></div></div><div class="flex">${badge('approved')}<button data-open="${e.id}">View consultation ${icon('chevron')}</button></div></section>`).join(''):'<div class="card empty">No approved consultations yet.</div>'}</div>`;}
function bindHistoryPage(){bindOpen();}
function consultation(){const e=active(),d=state.draft,locked=e.status==='approved';return heading('Consultation workspace','Capture what matters. Review the details. Give the patient a clear next step.',`<button id="back">${icon('arrow')} Back to queue</button>`)+`<section class="card patient-banner"><div class="flex"><div class="avatar mint">${esc(initials(e.name))}</div><div><h2>${esc(e.name)}</h2><div class="patient-meta"><span>${esc(e.mrn)}</span><span>${e.age} years · ${esc(e.sex)}</span><span>${esc(e.doctor_name)} · ${esc(e.specialty)}</span></div></div></div><div class="flex"><span class="token">Token #${e.token}</span>${badge(e.status)}<span class="micro muted">Revision ${e.version}</span></div></section><div class="workspace"><aside class="capture-panel stack"><section class="card"><div class="card-head"><h2 class="flex">${icon('mic')} Consultation capture</h2><span class="badge ${locked?'green':'purple'}">${locked?'Record saved':'Draft'}</span></div><div class="card-pad">${locked?`<div class="info">This consultation is approved. Start an amendment to make further changes. Previously issued versions are preserved.</div><button id="reopen" style="width:100%;margin-top:15px">${icon('plus')} Start an amendment</button>`:`<div class="info">Explain recording to the patient. Capture only after consent. Manual documentation remains available.</div><div class="consent">${[['granted','Consent granted'],['declined','Declined'],['manual','Manual only']].map(([v,l])=>`<button data-consent="${v}" class="${e.consent===v?'selected':''}">${l}</button>`).join('')}</div><div class="record-box ${state.recording?'recording':''}" id="record-box"><div class="record-icon">${icon('mic')}</div><div class="record-time" id="record-time">${timeString()}</div><div class="record-caption" id="record-caption">${state.recording?(state.paused?'Paused — microphone stream remains open':'Recording this consultation'):'Ready when you and the patient are'}</div><div class="record-actions"><button class="primary" id="record" ${e.consent!=='granted'||!state.data.ai_configured?'disabled':''}>${icon('mic')} ${state.recording?'Recording…':'Start recording'}</button><button id="pause" ${!state.recording?'disabled':''}>${icon('pause')} ${state.paused?'Resume':'Pause'}</button><button id="stop" ${!state.recording?'disabled':''}>${icon('stop')} Stop</button></div></div>`}<div class="flex between"><label for="transcript" style="margin:0">Consultation source</label><span class="micro muted">Review the transcript</span></div><textarea id="transcript" class="source-area" placeholder="Record the consultation, paste a fictional transcript, or document manually…" ${locked?'readonly':''}>${esc(state.transcript)}</textarea>${!locked?`<button class="primary" id="generate" style="width:100%" ${!state.data.ai_configured?'disabled':''}>${icon('spark')} Generate reviewable draft</button><button class="quiet small" id="load-demo" style="width:100%;margin-top:10px">${icon('book')} Load fictional walkthrough</button>`:''}<p class="micro muted" style="margin-top:14px">Audio is sent to the configured provider for transcription; this application does not retain the audio file. Provider retention is governed by your provider agreement.</p></div></section><section class="card"><div class="card-head"><h3 class="flex">${icon('history')} Previous approved visits</h3><span class="badge">${state.history.length}</span></div><div class="card-pad">${historySnippet()}</div></section></aside><section class="card"><div class="card-head"><div><h2>${locked?'Approved clinical record':'Clinical draft'}</h2><p class="micro muted" style="margin-top:5px">${locked?'Issued details are preserved in a versioned snapshot.':'Generated content is a proposal. Check every field before approval.'}</p></div><span class="badge ${locked?'green':'amber'}" id="save-status">${locked?'Approved':state.dirty?'Unsaved edits':'Saved'}</span></div>${locked?'':`<div class="card-pad" style="padding-bottom:0"><div class="info warning">The demonstration catalogue contains fictional medicines. Enter no real patient information.</div></div>`}<fieldset id="draft-fields" ${locked?'disabled':''} style="border:0;padding:0;margin:0;min-width:0"><section class="clinical-section"><div class="section-title">${icon('file')}<span class="eyebrow">01 · Patient story</span></div><div class="grid2">${textField('complaints','Presenting complaints','What brought the patient in?')}${textField('history','History & previous treatment','Duration, previous treatment and relevant history')}</div></section><section class="clinical-section"><div class="section-title">${icon('shield')}<span class="eyebrow">02 · Allergies & assessment</span></div><div class="grid2"><div><label for="field-allergy_status">Allergy assessment</label><select id="field-allergy_status" data-field="allergy_status">${[['not_assessed','Not assessed / not documented'],['none_reported','No allergies reported — clinician checked'],['reported','Reported allergy / adverse reaction'],['uncertain','Uncertain — needs clarification']].map(([v,l])=>`<option value="${v}" ${d.allergy_status===v?'selected':''}>${l}</option>`).join('')}</select></div><div>${textField('allergies','Allergy / reaction details','Record the substance and reaction; distinguish intolerance.')}</div><div class="span2">${textField('assessment','Clinician assessment / provisional diagnosis','Only the assessment stated by the clinician')}</div></div></section><section class="clinical-section"><div class="section-title between"><div class="flex">${icon('pill')}<span class="eyebrow">03 · Medicines & instructions</span></div><button class="small" id="add-med">${icon('plus')} Add medicine</button></div><div id="medicines">${medicinesHTML()}</div><div class="micro muted">Names are not automatically substituted. Each medicine and its schedule require clinician confirmation.</div></section><section class="clinical-section"><div class="section-title">${icon('heart')}<span class="eyebrow">04 · Patient’s next steps</span></div><div class="grid2">${textField('tests','Investigations / tests','Test names and timing only as specified')}${textField('diet','Diet & lifestyle','Only advice given during this consultation')}${textField('instructions','General instructions','Clear, patient-facing instructions')}${textField('followup','Follow-up','When to return, as specified by the doctor')}</div></section><section class="clinical-section"><div class="section-title">${icon('shield')}<span class="eyebrow">05 · Items needing review</span></div><div id="review-items">${reviewHTML()}</div></section></fieldset><div class="approval-box">${locked?`<div class="flex wrap"><button class="primary" id="print-current">${icon('print')} Prescription</button><button id="care-current">${icon('heart')} Patient care sheet</button><button id="all-history">${icon('history')} Version history</button></div>`:`<label class="check"><input id="attest" type="checkbox"> <span>I have checked the patient, clinical details, medicines and instructions. I take responsibility for approving this demonstration document.</span></label><div class="approval-actions"><button id="save">${icon('check')} Save draft</button><button id="amend">${icon('mic')} Add / correct details</button><button id="approve" class="primary">Approve & prepare print ${icon('chevron')}</button></div><p class="micro muted" style="margin-top:13px">Stopping a recording does not finalise this visit. You can add information before approval.</p>`}</div></section></div>`;}
function timeString(){return String(Math.floor(state.seconds/60)).padStart(2,'0')+':'+String(state.seconds%60).padStart(2,'0');}
function textField(key,label,placeholder){return `<div><label for="field-${key}">${label}</label><textarea id="field-${key}" data-field="${key}" placeholder="${esc(placeholder)}">${esc(state.draft[key])}</textarea></div>`;}
function medicinesHTML(){if(!state.draft.medicines.length)return `<div class="empty" style="padding:22px 10px">No medicines documented. Add only those explicitly prescribed.</div>`;return `<datalist id="catalogue">${state.data.catalogue.map(m=>`<option value="${esc(m.name)}">${esc(m.strength)} · ${esc(m.source)}</option>`).join('')}</datalist>`+state.draft.medicines.map((m,i)=>`<div class="medicine" data-med-row="${i}"><div class="medicine-top"><strong style="font-size:12px">Medicine ${i+1}</strong><button class="quiet small danger" data-remove-med="${i}" aria-label="Remove medicine ${i+1}">${icon('close')} Remove</button></div><div class="grid3">${[['name','Medicine / brand'],['strength','Strength / formulation'],['dose','Dose / quantity'],['route','Route'],['frequency','Frequency'],['timing','Timing / remarks'],['duration','Duration']].map(([k,l])=>`<div ${k==='name'?'class="span2"':''}><label for="med-${i}-${k}">${l}</label><input id="med-${i}-${k}" data-med="${i}" data-key="${k}" value="${esc(m[k])}" ${k==='name'?'list="catalogue"':''}></div>`).join('')}</div>${m.evidence?`<div class="evidence">Source: “${esc(m.evidence)}”</div>`:''}<label class="check"><input type="checkbox" data-confirm-med="${i}" ${m.confirmed?'checked':''}><span>I checked this medicine’s identity and complete instructions.</span></label></div>`).join('');}
function reviewHTML(){return state.draft.uncertainties.length?state.draft.uncertainties.map((x,i)=>`<div class="review-item">${icon('shield')}<p>${esc(x)}</p><button class="quiet" data-resolve="${i}" aria-label="Mark review item ${i+1} resolved">${icon('check')}</button></div>`).join(''):`<p class="micro muted">No flagged review items. The full record still requires clinician review.</p>`;}
function historySnippet(){if(!state.history.length)return `<p class="muted micro">No previous approved visits in this hospital.</p>`;const ids=new Set(state.history.map(d=>d.supersedes).filter(Boolean));return state.history.slice(0,4).map(d=>`<div class="journey-item"><div class="step">${icon('file')}</div><div><h3>${date(d.created)} ${ids.has(d.id)?'<span class="badge amber">Superseded</span>':''}</h3><p>${esc(d.snapshot.doctor.name)} · ${esc(d.snapshot.doctor.specialty)}</p><p>${esc(d.snapshot.draft.complaints)}</p><button class="quiet small" data-doc="${d.id}">View approved record ${icon('chevron')}</button></div></div>`).join('');}
function markDirty(){state.dirty=true;const el=$('#save-status');if(el){el.textContent='Unsaved edits';el.className='badge amber';}const a=$('#attest');if(a)a.checked=false;}
function collect(){if(!state.active)return;$$('[data-field]').forEach(el=>state.draft[el.dataset.field]=el.value);$$('[data-med]').forEach(el=>state.draft.medicines[+el.dataset.med][el.dataset.key]=el.value);$$('[data-confirm-med]').forEach(el=>state.draft.medicines[+el.dataset.confirmMed].confirmed=el.checked);if($('#transcript'))state.transcript=$('#transcript').value;}
function bindDraft(){ $$('[data-field]').forEach(el=>el.oninput=()=>{collect();markDirty();});$$('[data-med]').forEach(el=>el.oninput=()=>{const i=+el.dataset.med;collect();state.draft.medicines[i].confirmed=false;const cb=$(`[data-confirm-med="${i}"]`);if(cb)cb.checked=false;markDirty();});$$('[data-confirm-med]').forEach(el=>el.onchange=()=>{collect();markDirty();});$$('[data-remove-med]').forEach(b=>b.onclick=()=>{collect();state.draft.medicines.splice(+b.dataset.removeMed,1);markDirty();$('#medicines').innerHTML=medicinesHTML();bindDraft();});$$('[data-resolve]').forEach(b=>b.onclick=()=>{if(!confirm('Have you checked the source and corrected or clarified this item?'))return;collect();state.draft.uncertainties.splice(+b.dataset.resolve,1);markDirty();$('#review-items').innerHTML=reviewHTML();bindDraft();});}
async function saveDraft(){collect();const id=state.active;await api(`encounters/${id}/draft`,{version:active().version,draft:state.draft,transcript:state.transcript});await refresh();state.draft=clone(active().draft);state.dirty=false;}
function bindConsultation(){bindDraft();$('#back').onclick=()=>{if(!allowNavigate())return;state.active=null;state.dirty=false;state.page='queue';render();};$$('[data-doc]').forEach(b=>b.onclick=()=>showDocument(b.dataset.doc));const e=active();if(e.status==='approved'){$('#reopen').onclick=reopenModal;$('#print-current').onclick=()=>showDocument(currentDoc()?.id);$('#care-current').onclick=()=>showDocument(currentDoc()?.id,true);$('#all-history').onclick=historyModal;return;}
$('#transcript').oninput=()=>{state.transcript=$('#transcript').value;markDirty();};$$('[data-consent]').forEach(b=>b.onclick=()=>run(async()=>{if(state.recording)throw new Error('Stop recording before changing consent.');collect();if(state.dirty)await saveDraft();await api(`encounters/${state.active}/consent`,{version:active().version,consent:b.dataset.consent});await refresh();render();}));$('#record').onclick=startRecording;$('#pause').onclick=pauseRecording;$('#stop').onclick=stopRecording;
$('#add-med').onclick=()=>{collect();state.draft.medicines.push({id:'',name:'',strength:'',dose:'',route:'',frequency:'',timing:'',duration:'',evidence:'',confirmed:false});markDirty();$('#medicines').innerHTML=medicinesHTML();bindDraft();};$('#save').onclick=()=>run(async()=>{if(state.recording)throw new Error('Stop recording before saving.');await saveDraft();render();toast('Draft saved. It has not been issued.');});$('#generate').onclick=()=>propose();$('#amend').onclick=amendModal;$('#load-demo').onclick=loadDemo;$('#approve').onclick=()=>run(async()=>{if(state.recording)throw new Error('Stop recording before approval.');collect();if(!$('#attest').checked)throw new Error('Confirm your clinical review before approval.');await saveDraft();const id=state.active;const result=await api(`encounters/${id}/approve`,{version:active().version,attest:true});await refresh();state.history=(await api(`encounters/${id}/history`)).documents;render();showDocument(result.id);toast('Demonstration document approved and saved.');});}
function currentDoc(){return state.history.filter(d=>d.encounter===state.active).sort((a,b)=>b.version-a.version)[0];}
function stopTracks(){if(state.stream)state.stream.getTracks().forEach(t=>t.stop());state.stream=null;clearInterval(state.timer);}
async function startRecording(){if(state.recording||state.busy)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('Microphone recording needs HTTPS or localhost and a supported browser. Manual entry is available.',true);collect();const encounterId=state.active;let chunks=[];try{state.stream=await navigator.mediaDevices.getUserMedia({audio:true});if(encounterId!==state.active){stopTracks();return;}const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(m=>MediaRecorder.isTypeSupported(m));state.recorder=new MediaRecorder(state.stream,mime?{mimeType:mime}:{});state.seconds=0;state.paused=false;state.recording=true;state.recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};state.recorder.onstop=()=>{const blob=new Blob(chunks,{type:state.recorder.mimeType});stopTracks();state.recording=false;state.paused=false;render();run(async()=>{if(blob.size>14*1024*1024)throw new Error('Recording exceeds the segment limit. Please use shorter recordings or type the transcript.');toast('Transcribing this recording…');const buffer=await blob.arrayBuffer();let binary='';const bytes=new Uint8Array(buffer);for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const r=await api(`encounters/${encounterId}/transcribe`,{version:active().version,audio:btoa(binary),mime:blob.type});if(encounterId!==state.active)throw new Error('Patient changed. Recording was not applied.');state.transcript+=(state.transcript?'\n\n':'')+r.transcript;markDirty();render();toast('Transcript added. Review it before generating a draft.');});};state.recorder.start(1000);state.timer=setInterval(()=>{if(!state.paused){state.seconds++;const time=$('#record-time');if(time)time.textContent=timeString();if(state.seconds>=600)stopRecording();}},1000);render();}catch(e){state.recording=false;stopTracks();toast('Microphone could not start: '+e.message,true);}}
function pauseRecording(){if(!state.recorder||!state.recording)return;collect();if(state.paused)state.recorder.resume();else state.recorder.pause();state.paused=!state.paused;render();}
function stopRecording(){if(state.recorder&&state.recorder.state!=='inactive'){collect();state.recorder.stop();clearInterval(state.timer);}}
window.addEventListener('beforeunload',e=>{if(state.recording||state.dirty){e.preventDefault();e.returnValue='';}});
function loadDemo(){collect();if(state.recording)return toast('Stop recording first.',true);if(state.dirty&&!confirm('Replace unsaved work with the fictional walkthrough?'))return;state.transcript='FICTIONAL DEMONSTRATION — NOT CLINICAL ADVICE\nPatient: This is a fictional follow-up consultation. I have no known allergies that I can recall.\nDoctor: I have checked your reported allergy history. For the product demonstration only: Demo Medicine A, strength 10 demo units, one fictional tablet by mouth once each morning for 3 demo days.\nDoctor: Bring your previous test reports to the next visit. Keep your usual diet; no additional diet plan was discussed. Follow up in one demo week.';state.draft={complaints:'Fictional follow-up consultation',history:'Patient reports a previous consultation. Prior records should be reviewed.',allergy_status:'none_reported',allergies:'',assessment:'Fictional assessment for workflow demonstration only',medicines:[{id:'',name:'Demo Medicine A',strength:'10 demo units',dose:'One fictional tablet',route:'Oral — fictional',frequency:'Once daily',timing:'Morning',duration:'3 demo days',evidence:'Doctor: Demo Medicine A, strength 10 demo units, one fictional tablet by mouth once each morning for 3 demo days.',confirmed:false}],tests:'Bring previous test reports. No new investigation ordered in this fictional example.',diet:'Keep the usual diet, as stated in the fictional consultation.',instructions:'Bring your previous records to the next visit.',followup:'One demo week',uncertainties:['Clinician must confirm the fictional medicine and complete instructions before approval.']};markDirty();render();toast('Loaded a scripted fictional example. No AI processing was used.');}
function modal(title,body,footer='',wide=false){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="quiet icon-button" id="modal-close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;$('#modal-close').onclick=closeModal;const el=$('input,textarea,select,button',$('.modal-body'));if(el)el.focus();}
function closeModal(){if(state.busy)return;$('#modal-root').innerHTML='';state.proposal=null;}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!state.busy&&$('#modal-root').children.length)closeModal();if(e.key==='Tab'&&$('#modal-root').children.length){const items=$$('button,input,textarea,select,a[href]', $('.modal')).filter(x=>!x.disabled&&x.offsetParent!==null);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function patientModal(){modal('Add a fictional patient',`<div class="info warning row">Use fictional details only. This release is not enabled for real-patient records.</div><form id="patient-form" class="stack"><div><label for="pname">Patient name</label><input id="pname" required maxlength="120" placeholder="Fictional patient name"></div><div class="grid2"><div><label for="page">Age (adult OPD)</label><input id="page" type="number" min="18" max="120" required></div><div><label for="psex">Sex</label><select id="psex"><option>Female</option><option>Male</option><option>Other</option><option>Not specified</option></select></div></div><div><label for="pphone">Contact number (optional)</label><input id="pphone" maxlength="30" placeholder="Use a fictional contact"></div><button class="primary" type="submit">Save fictional patient</button></form>`);$('#patient-form').onsubmit=ev=>{ev.preventDefault();run(async()=>{await api('patients',{name:$('#pname').value,age:$('#page').value,sex:$('#psex').value,phone:$('#pphone').value});await refresh();$('#modal-root').innerHTML='';render();toast('Fictional patient created. Register a visit from the queue.');});};}
function visitModal(){modal('Register a visit',`<form id="visit-form" class="stack"><div class="info">Select the hospital patient ID as well as the name. A new token will be assigned for the selected doctor.</div><div><label for="vpatient">Existing fictional patient</label><select id="vpatient" required><option value="">Select a patient</option>${state.data.patients.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.mrn)} · ${p.age}y</option>`).join('')}</select></div><div><label for="vdoctor">Assigned doctor</label><select id="vdoctor" required><option value="">Select a doctor</option>${state.data.doctors.map(d=>`<option value="${d.id}">${esc(d.name)} · ${esc(d.specialty)}</option>`).join('')}</select></div><button class="primary" type="submit">Register & assign token</button><button type="button" id="add-from-visit" class="quiet">New patient? Create a fictional record first</button></form>`);$('#add-from-visit').onclick=patientModal;$('#visit-form').onsubmit=ev=>{ev.preventDefault();run(async()=>{const r=await api('encounters',{patient:$('#vpatient').value,doctor:$('#vdoctor').value});await refresh();$('#modal-root').innerHTML='';render();toast('Visit registered. Token #'+r.token);});};}
function amendModal(){if(state.recording)return toast('Stop the recording first. You can then add or correct details.',true);collect();modal('Add information or correct the draft',`<div class="info row">You can edit the clinical fields directly, or ask the connected AI to propose a change. Every proposed change needs your review. Record another segment from the consultation panel if needed.</div><label for="amend-instruction">Clinician’s amendment instruction</label><textarea id="amend-instruction" placeholder="For example: remove the fictional Medicine A. Document the reported reaction separately. Add the replacement only with the exact instructions I specify." style="min-height:140px"></textarea><p class="micro muted" style="margin-top:12px">The patient's statement alone does not authorise a treatment change. Missing replacement details must be entered and checked by the doctor.</p>`,`<button id="manual-amend">Edit fields manually</button><button class="primary" id="propose" ${!state.data.ai_configured?'disabled':''}>${icon('spark')} Propose changes</button>`);$('#manual-amend').onclick=()=>{closeModal();$('#field-history').focus();};$('#propose').onclick=()=>propose($('#amend-instruction').value);}
async function propose(instruction=null){if(state.recording)return toast('Stop recording before generating a proposal.',true);collect();await run(async()=>{const id=state.active;await saveDraft();const r=await api(`encounters/${id}/${instruction===null?'generate':'propose-amendment'}`,{version:active().version,draft:state.draft,transcript:state.transcript,instruction:instruction||''});state.proposal={draft:r.proposal,version:r.version,id};proposalModal();});}
function proposalModal(){const proposed=state.proposal.draft;const keys=Object.keys(proposed).filter(k=>JSON.stringify(proposed[k])!==JSON.stringify(state.draft[k]));const printable=v=>Array.isArray(v)?v.map(x=>typeof x==='string'?x:JSON.stringify(x,null,2)).join('\n\n')||'(empty)':v||'(empty)';modal('Review proposed changes',`<div class="info warning row">This proposal has not changed the clinical record. Review every difference, especially medicines, numbers, omissions and negation.</div>${keys.length?keys.map(k=>`<div class="diff"><h3>${esc(k.replaceAll('_',' '))}</h3><div class="diff-old"><strong>Current</strong>\n${esc(printable(state.draft[k]))}</div><div class="diff-new"><strong>Proposed</strong>\n${esc(printable(proposed[k]))}</div></div>`).join(''):'<p>No differences were proposed.</p>'}`,`<button id="reject-proposal">Discard proposal</button><button class="primary" id="accept-proposal">Apply to editable draft</button>`,true);$('#reject-proposal').onclick=closeModal;$('#accept-proposal').onclick=()=>{if(state.active!==state.proposal.id||active().version!==state.proposal.version)return toast('The record changed. Discard and generate a fresh proposal.',true);state.draft=clone(state.proposal.draft);markDirty();closeModal();render();toast('Proposal applied to your local draft. Review and save before approval.');};}
function reopenModal(){modal('Amend an approved consultation',`<div class="info row">The issued document remains preserved. A new version will require another review and approval. Previously printed copies cannot be recalled automatically.</div><label for="reopen-reason">Reason for amendment</label><textarea id="reopen-reason" required placeholder="What new information or correction requires this change?"></textarea>`,`<button class="primary" id="confirm-reopen">Start versioned amendment</button>`);$('#confirm-reopen').onclick=()=>run(async()=>{await api(`encounters/${state.active}/reopen`,{version:active().version,reason:$('#reopen-reason').value});await refresh();state.draft=clone(active().draft);state.dirty=false;$('#modal-root').innerHTML='';render();});}
function historyModal(){const superseded=new Set(state.history.map(d=>d.supersedes).filter(Boolean));modal('Patient’s approved record history',`<div class="timeline">${state.history.map(d=>`<div class="timeline-card card card-pad"><div class="flex between"><h3>${date(d.created)}</h3><span class="badge ${superseded.has(d.id)?'amber':'green'}">${superseded.has(d.id)?'Superseded':'Approved'}</span></div><p class="muted" style="margin-top:8px">${esc(d.snapshot.doctor.name)} · ${esc(d.snapshot.doctor.specialty)} · Revision ${d.version}</p><p style="margin-top:10px">${esc(d.snapshot.draft.complaints)}</p><button class="small" data-history-doc="${d.id}" style="margin-top:12px">View document</button></div>`).join('')}</div>`,'',true);$$('[data-history-doc]').forEach(b=>b.onclick=()=>showDocument(b.dataset.historyDoc));}
function showDocument(id,care=false){const doc=state.history.find(d=>d.id===id);if(!doc)return toast('Approved document not found. Refresh this visit.',true);const s=doc.snapshot,d=s.draft;const superseded=state.history.some(x=>x.supersedes===id);const labels={not_assessed:'Not documented',none_reported:'No allergies reported — clinician checked',reported:'Reported allergy / adverse reaction',uncertain:'Uncertain'};let body=`<article class="document"><div class="doc-demo">FICTIONAL DEMONSTRATION — NOT A VALID CLINICAL PRESCRIPTION${superseded?' · SUPERSEDED VERSION':''}</div><div class="doc-header flex between wrap"><div><h1>${esc(s.organisation.name)}</h1><p class="muted" style="margin-top:6px">${esc(s.organisation.address)}</p></div><div style="text-align:right"><h3>${care?'Patient care sheet':'Outpatient consultation'}</h3><p>${date(doc.created)} · Token #${s.token}</p></div></div><div class="patient-details"><div><strong>${esc(s.patient.name)}</strong><br>${esc(s.patient.mrn)} · ${s.patient.age}y · ${esc(s.patient.sex)}</div><div>${esc(s.doctor.name)}<br>${esc(s.doctor.specialty)}</div></div>`;
if(care){body+=`<p>Your doctor-approved instructions from this fictional consultation. Only the advice documented for this visit is shown.</p><h2>Medicines and schedule</h2>${d.medicines.length?d.medicines.map((m,i)=>`<section class="care-section"><h3><span class="care-number">${i+1}.</span>${esc(m.name)} · ${esc(m.strength)}</h3><p>${esc(m.dose)} · ${esc(m.route)}\n${esc(m.frequency)}${m.timing?' · '+esc(m.timing):''}\nDuration: ${esc(m.duration)}</p></section>`).join(''):'<p>No medicines documented for this visit.</p>'}${[['Tests / investigations',d.tests],['Diet and lifestyle',d.diet],['General instructions',d.instructions],['Follow-up',d.followup]].map(([l,v])=>`<section class="care-section"><h3>${l}</h3><p>${esc(v)||'Not specified during this consultation.'}</p></section>`).join('')}`;
}else{body+=[['Presenting complaints',d.complaints],['Relevant history / previous treatment',d.history],['Allergies / adverse reactions',(labels[d.allergy_status]||d.allergy_status)+(d.allergies?'\n'+d.allergies:'')],['Clinician assessment',d.assessment]].map(([l,v])=>`<h2>${l}</h2><p>${esc(v)||'Not documented'}</p>`).join('');body+=`<h2>Medicines</h2>${d.medicines.length?`<table><thead><tr><th>Medicine / strength</th><th>Dose / route</th><th>Frequency / timing</th><th>Duration</th></tr></thead><tbody>${d.medicines.map(m=>`<tr><td><strong>${esc(m.name)}</strong><br>${esc(m.strength)}</td><td>${esc(m.dose)}<br>${esc(m.route)}</td><td>${esc(m.frequency)}<br>${esc(m.timing)}</td><td>${esc(m.duration)}</td></tr>`).join('')}</tbody></table>`:'<p>No medicines documented.</p>'}`;body+=[['Investigations / tests',d.tests],['Diet and lifestyle',d.diet],['General instructions',d.instructions],['Follow-up',d.followup]].map(([l,v])=>`<h2>${l}</h2><p>${esc(v)||'Not specified'}</p>`).join('');}
body+=`<div class="signature"><strong>Approved in demonstration by ${esc(s.doctor.name)}</strong><br>Registration: ${esc(s.doctor.registration)||'Not provided'}</div><div class="doc-version">Document ${esc(doc.id)} · Revision ${doc.version} · Approved ${esc(doc.created)}${s.reason?' · Amendment reason: '+esc(s.reason):''}<br>This fictional document does not establish a diagnosis or provide treatment advice.</div></article>`;modal(care?'Patient care sheet':'Approved prescription',body,`<button id="toggle-document">${icon(care?'file':'heart')} ${care?'Clinical prescription':'Patient care sheet'}</button><button class="primary" id="print-document">${icon('print')} Print / save PDF</button>`,true);$('#toggle-document').onclick=()=>showDocument(id,!care);$('#print-document').onclick=()=>window.print();}
function settings(){const d=state.data;return heading('Hospital settings','Manage the team, organisation details and access activity.')+`<div class="grid2"><section class="card"><div class="card-head"><h2>Hospital identity</h2></div><form id="org-form" class="card-pad stack"><div><label for="org-name">Hospital name</label><input id="org-name" value="${esc(d.organisation.name)}" required></div><div><label for="org-address">Address</label><textarea id="org-address">${esc(d.organisation.address)}</textarea></div><div><label for="org-phone">Contact</label><input id="org-phone" value="${esc(d.organisation.phone)}"></div><button class="primary" type="submit">Save hospital details</button></form></section><section class="card card-pad"><div class="feature-icon">${icon('shield')}</div><h2>Demonstration release</h2><p class="muted" style="margin:14px 0;font-size:12px">Real-patient mode is disabled in this build. Provider connection does not make this a clinically validated system.</p><div class="info">${d.ai_configured?'AI key configured on the server. Validate transcription, extraction, retention terms and operating costs before clinical evaluation.':'AI not configured. Add OPENAI_API_KEY on the server to test real speech transcription and structured extraction with fictional cases.'}</div><ul class="note-list"><li>Role and hospital access checks</li><li>Versioned clinician approvals</li><li>Record-access and change activity</li><li>Manual documentation remains available</li></ul></section><section class="card span2"><div class="card-head"><h2>Hospital team</h2><button id="add-user" class="primary small">${icon('plus')} Add team member</button></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Specialty</th></tr></thead><tbody>${d.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td><span class="badge purple">${esc(u.role)}</span></td><td>${esc(u.specialty)||'—'}</td></tr>`).join('')}</tbody></table></div></section><section class="card span2"><div class="card-head"><h2>Recent access & change activity</h2><span class="micro muted">Latest 100 events · UTC timestamps</span></div><div class="table-wrap"><table><thead><tr><th>Event</th><th>Actor</th><th>Time</th></tr></thead><tbody>${d.audit.map(a=>`<tr><td>${esc(a.action.replaceAll('_',' '))}</td><td>${esc(a.actor||a.user)}</td><td>${esc(a.created)}</td></tr>`).join('')}</tbody></table></div></section></div>`;}
function bindSettings(){$('#org-form').onsubmit=e=>{e.preventDefault();run(async()=>{await api('organisation',{name:$('#org-name').value,address:$('#org-address').value,phone:$('#org-phone').value});await refresh();render();toast('Hospital details updated. Previously approved documents retain their original details.');});};$('#add-user').onclick=()=>{modal('Add a hospital team member',`<form id="user-form" class="stack"><div class="grid2"><div><label for="uname">Name</label><input id="uname" required></div><div><label for="uemail">Email</label><input id="uemail" type="email" required></div><div><label for="urole">Role</label><select id="urole"><option value="doctor">Doctor</option><option value="reception">Reception</option><option value="admin">Administrator</option></select></div><div><label for="uspecialty">Specialty / department</label><input id="uspecialty"></div><div><label for="ureg">Doctor registration number</label><input id="ureg"></div><div><label for="upassword">Initial password (16+ characters)</label><input id="upassword" type="password" minlength="16" required autocomplete="new-password"></div></div><button class="primary">Create team member</button></form>`);$('#user-form').onsubmit=e=>{e.preventDefault();run(async()=>{await api('users',{name:$('#uname').value,email:$('#uemail').value,role:$('#urole').value,specialty:$('#uspecialty').value,registration:$('#ureg').value,password:$('#upassword').value});await refresh();$('#modal-root').innerHTML='';render();toast('Team member added. They can change their password from their account menu.');});};};}
function passwordModal(){if(state.recording)return;modal('Change your password',`<form id="pw-form" class="stack"><div><label for="oldpw">Current password</label><input id="oldpw" type="password" autocomplete="current-password" required></div><div><label for="newpw">New password (16+ characters)</label><input id="newpw" type="password" autocomplete="new-password" minlength="16" required></div><button class="primary">Update password</button></form>`);$('#pw-form').onsubmit=e=>{e.preventDefault();run(async()=>{await api('password',{old:$('#oldpw').value,new:$('#newpw').value});$('#modal-root').innerHTML='';toast('Password updated. Other sessions have been signed out.');});};}
(async()=>{try{await refresh();render();}catch(e){if(!state.data)renderLogin();}})();
